// Python float() -> str(float) -> Decimal -> quantize ROUND_HALF_EVEN -> group
function pyFloat(s){
  // unicode decimal digit folding is done by caller for simplicity (ASCII input only here)
  const t = s.trim();
  if(!/^[+-]?((\d(_?\d)*)?\.?(\d(_?\d)*)?)([eE][+-]?\d(_?\d)*)?$/.test(t)) return NaN;
  const u = t.replace(/_/g,'');
  if(!/\d/.test(u)) return NaN;
  return Number(u);
}
// exact decimal digits of shortest round-trip repr, as {sign, digits, exp} value = sign*0.digits *10^exp? use coeff/exp form
function reprDec(x){
  if(!isFinite(x)) return null;
  let s = Math.abs(x).toExponential(); // shortest? no
  // use String() which is shortest round-trip
  s = Math.abs(x).toString();
  let sign = (x<0 || (x===0 && 1/x<0)) ? -1 : 1;
  let m, e=0;
  const em = s.match(/^(\d*)(?:\.(\d*))?[eE]([+-]?\d+)$/);
  if(em){ m = em[1] + (em[2]||''); e = parseInt(em[3],10) - (em[2]||'').length; }
  else { const p = s.split('.'); m = p[0] + (p[1]||''); e = -((p[1]||'').length); }
  m = m.replace(/^0+(?=\d)/,'');
  return {sign, coeff: m, exp: e}; // value = sign * coeff * 10^exp
}
function quantizeHalfEven(d, places){
  // returns string of digits with exactly `places` decimals (unsigned), plus sign
  let {sign, coeff, exp} = d;
  // build full digit string with decimal point position
  let digits = coeff;
  let pointFromRight = -exp; // number of fractional digits
  if(pointFromRight < 0){ digits = digits + '0'.repeat(-pointFromRight); pointFromRight = 0; }
  // now value = digits with pointFromRight fractional digits
  if(pointFromRight <= places){
    digits = digits + '0'.repeat(places - pointFromRight);
    pointFromRight = places;
  } else {
    const drop = pointFromRight - places;
    const keep = digits.slice(0, digits.length - drop) || '0';
    const rem = digits.slice(digits.length - drop);
    let roundUp = false;
    const first = rem[0];
    if(first > '5') roundUp = true;
    else if(first === '5'){
      if(/[1-9]/.test(rem.slice(1))) roundUp = true;
      else { const last = keep[keep.length-1]||'0'; roundUp = (parseInt(last,10)%2)===1; }
    }
    let k = keep;
    if(roundUp){ k = (BigInt(k||'0')+1n).toString(); }
    digits = k; pointFromRight = places;
  }
  digits = digits.replace(/^0+(?=\d)/,'');
  while(digits.length < pointFromRight+1) digits = '0'+digits;
  const ip = digits.slice(0, digits.length-places) || '0';
  const fp = places? digits.slice(digits.length-places) : '';
  return {sign, ip, fp, totalDigits: digits.replace(/^0+(?=\d)/,'').length};
}
function group(ip){ return ip.replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
const CUR={USD:{d:2,pre:'$',post:''},CLF:{d:4,pre:'CLF',post:''},JPY:{d:0,pre:'¥',post:''},XXX:{d:2,pre:'¤',post:''}};
function fmt(arg, cur){
  const x = pyFloat(arg);
  if(Number.isNaN(x) && !/nan/i.test(arg.trim())) return 'ERR';
  const c = CUR[cur];
  if(!isFinite(x)){
    if(Number.isNaN(x)) return c.pre + 'NaN' + (c.d? '.'+'0'.repeat(c.d):'');
    return (x<0?'-':'') + c.pre + '∞';
  }
  const d = reprDec(x);
  const q = quantizeHalfEven(d, c.d);
  // integer digit count check
  const intDigits = q.ip === '0' ? 1 : q.ip.length;
  const total = (q.ip==='0'? 1 : q.ip.length) + c.d;
  if(total > 28) return 'INVALIDOP';
  return (q.sign<0?'-':'') + c.pre + group(q.ip) + (c.d? '.'+q.fp : '');
}
const args=process.argv.slice(2);
console.log(fmt(args[0], args[1]||'USD'));
EOF
